package com.scriptles.cabinet.profile.service;
import com.scriptles.cabinet.common.api.*; import com.scriptles.cabinet.profile.dto.*; import com.scriptles.cabinet.profile.entity.*; import com.scriptles.cabinet.profile.enums.*; import com.scriptles.cabinet.profile.repository.*; import com.scriptles.cabinet.user.repository.UserRepository; import lombok.RequiredArgsConstructor; import org.springframework.data.domain.PageRequest; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.Instant; import java.util.*;
@Service @RequiredArgsConstructor public class PostService { private final PostRepository posts; private final ProfileRepository profiles; private final HQProfileRepository hqs;
 @Transactional(readOnly=true) public PageResponse<PostResponse> list(String handle,int page,int size){ Profile p=profiles.findByHandleIgnoreCase(handle).orElseThrow(()->err("PROFILE_NOT_FOUND","Perfil não encontrado")); return PageResponse.from(posts.findByAuthorProfileIdAndStatusOrderByPublishedAtDesc(p.getId(),PostStatus.PUBLISHED,PageRequest.of(page,size)).map(this::to)); }
 @Transactional public PostResponse create(UUID accountId,UUID profileId,PostRequest request){ throw err("HQ_FORBIDDEN","Use o painel da HQ para publicar"); }
 @Transactional public PostResponse createByOperator(UUID profileId,PostRequest request){ Profile p=profiles.findById(profileId).orElseThrow(()->err("PROFILE_NOT_FOUND","Perfil não encontrado")); HQProfile h=hqs.findByProfileId(profileId).orElseThrow(()->err("HQ_FORBIDDEN","Somente HQs podem publicar")); if(h.getClaimStatus()!=HQClaimStatus.CLAIMED) throw err("HQ_FORBIDDEN","HQ indisponível para publicação"); Post post=new Post();post.setAuthorProfile(p);post.setType(request.type());post.setTitle(request.title());post.setBody(request.body());post.setLinkUrl(request.linkUrl()); if(request.publish()){post.setStatus(PostStatus.PUBLISHED);post.setPublishedAt(Instant.now());} return to(posts.save(post)); }
 private PostResponse to(Post p){return new PostResponse(p.getId(),p.getAuthorProfile().getId(),p.getType(),p.getTitle(),p.getBody(),p.getLinkUrl(),p.getPublishedAt());} private ApiException err(String c,String m){return new ApiException(HttpStatus.FORBIDDEN,c,m);} }
